const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Kolkata' });
const sameDay = (row) => !!row.createdAt && new Date(row.createdAt).toLocaleDateString('en-CA', { timeZone: 'Asia/Kolkata' }) === today;
const appts = $('Get Appointments').all().map((i) => i.json).filter((r) => r.appointment_id && sameDay(r));
const logs = $('Get Message Log').all().map((i) => i.json).filter((r) => r.message_id && sameDay(r));
const failed = $('Get Failed Messages').all().map((i) => i.json).filter((r) => r.workflow_name && sameDay(r));
const received = logs.filter((r) => r.stage === 'received').length;
const replies = logs.filter((r) => r.stage === 'reply');
const count = (kind) => replies.filter((r) => r.outcome === kind).length;
const byDept = {};
for (const a of appts) { byDept[a.department] = (byDept[a.department] || 0) + 1; }
const deptLines = Object.keys(byDept).map((k) => k + ': ' + byDept[k]).join(', ') || 'none';
const text = 'Hospital bot daily report for ' + today + '\n'
  + 'Messages received: ' + received + '\n'
  + 'Appointments booked: ' + appts.length + ' (' + deptLines + ')\n'
  + 'Emergencies flagged: ' + count('emergency') + '\n'
  + 'Blocked attacks: ' + count('refuse') + '\n'
  + 'Unclear requests: ' + count('unclear') + '\n'
  + 'Slot already taken: ' + count('time_taken') + '\n'
  + 'Errors: ' + failed.length;
return [{ json: { owner_chat_id: 'OWNER_CHAT_ID_HERE', text: text } }];
